// ─────────────────────────────────────────────────────────────────────────────
// CAR — a real white Hyundai Elite i20, built from a photograph in layers
// (generated by scripts/build-car-assets.py):
//
//   .car__shadow            soft ground shadow (doesn't pitch with the body)
//   .car__layer--paint      the photo, with both alloy wheels re-laid as discs
//                           that spin inside their perspective ellipses
//   .car__layer--lines      blueprint drawing traced from the same photo
//
// Photo: Vauxford, Wikimedia Commons, CC BY-SA 4.0 (credited in the footer).
//
// Everything moves through CSS custom properties on the .car element:
//   --rot    wheel rotation (deg)        --pitch  body pitch (deg, + = nose down)
//   --lift   body vertical offset (px)   --flat   front sag from a soft tyre (0–1)
//   --paint  photo reveal over drawing   --lights headlamp intensity (0–1)
// ─────────────────────────────────────────────────────────────────────────────

// Coordinate space of the cut-out photo; hotspots and overlays use it too.
const W = 2284;
const H = 1219;

// Alloy rims as they appear in the photo (keep in sync with build-car-assets.py).
const WHEELS = {
  front: { cx: 1106, cy: 978, rx: 112, ry: 170, tilt: 8 },
  rear: { cx: 172, cy: 738, rx: 60, ry: 124, tilt: 3 },
};
const WHEEL_PAD = 1.06;

const MEDIA = '/media/car';
const pct = (v, total) => `${((v / total) * 100).toFixed(3)}%`;

function wheel(name) {
  const w = WHEELS[name];
  const size = 2 * w.ry * WHEEL_PAD;
  const style = `left:${pct(w.cx, W)};top:${pct(w.cy, H)};width:${pct(size, W)};` +
    `transform:translate(-50%,-50%) rotate(${w.tilt}deg) scaleX(${(w.rx / w.ry).toFixed(4)})`;
  return `<span class="car__wheel" style="${style}"><img src="${MEDIA}/wheel-${name}.webp" alt="" decoding="async" /></span>`;
}

const img = (name, eager) =>
  `<img class="car__img" src="${MEDIA}/${name}.webp" srcset="${MEDIA}/${name}-sm.webp 900w, ${MEDIA}/${name}.webp 1600w"
    sizes="(max-width: 760px) 100vw, 60vw" width="${W}" height="${H}" alt="" decoding="async" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'} />`;

/**
 * Renders the car into `el`. Options:
 *   lines  – include the blueprint line-drawing layer
 *   beam   – include headlamp glow + tail-lamp glow
 *   eager  – load immediately (hero) instead of lazily
 */
export function mountCar(el, { lines = false, beam = false, eager = false } = {}) {
  el.classList.add('car');
  el.innerHTML = `
    <img class="car__shadow" src="${MEDIA}/i20-shadow.webp" alt="" decoding="async" />
    <div class="car__layer car__layer--paint">
      <div class="car__body">
        ${img('i20-body', eager)}
        ${wheel('rear')}${wheel('front')}
        ${beam ? '<span class="car__lamp car__lamp--head"></span><span class="car__lamp car__lamp--fog"></span><span class="car__lamp car__lamp--tail"></span>' : ''}
      </div>
    </div>
    ${lines ? `<div class="car__layer car__layer--lines"><div class="car__body">${img('i20-lines', false)}</div></div>` : ''}
    ${beam ? '<div class="car__beam"></div>' : ''}`;
  return el;
}

export const CAR_VIEWBOX = { width: W, height: H };

// Tyre radius ÷ car image width; used to turn distance travelled into wheel rotation.
export const WHEEL_RADIUS_RATIO = 225 / W;

// Ground geometry measured from the photo (image units), used to lay the road
// under the car and to move the car along its real direction of travel.
// The photo is a front three-quarter view, so "forward" points right and
// towards the camera (down the screen), not straight across.
export const GROUND = {
  rearContact: { x: 203, y: 906 },     // lowest point of the rear tyre
  frontContact: { x: 1140, y: 1208 },  // lowest point of the front tyre
  lateral: { x: 0.98, y: -0.199 },     // car's left→right axis (front bumper line)
  unitsPerMetre: 500,                  // lateral scale (bumper ≈ 1.6 m wide)
  horizon: 0.1,                        // camera eye level, as a fraction of image height
};
const dx = GROUND.frontContact.x - GROUND.rearContact.x;
const dy = GROUND.frontContact.y - GROUND.rearContact.y;
const len = Math.hypot(dx, dy);
export const HEADING = { x: dx / len, y: dy / len };
// Longitudinal scale: rear-to-front contact = the i20's 2.57 m wheelbase.
GROUND.unitsPerMetreLong = len / 2.57;
